components.css:
.ds-btn-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 32px;
  padding: 0 15px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: var(--color-leather-600);
  color: #ffffff;
  font-family: var(--font-sans);
  font-size: 14px;
  font-weight: 400;
  line-height: 1;
  cursor: pointer;
  transition: background-color 200ms ease, border-color 200ms ease;
}
.ds-btn-primary--large {
  height: 40px;
  padding: 0 16px;
  font-size: 16px;
}
.ds-btn-primary:hover {
  background: var(--color-leather-700);
}
.ds-btn-primary:active {
  background: var(--color-leather-700);
  box-shadow: inset 0 1px 2px rgb(0 0 0 / 18%);
}
.ds-btn-primary:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--color-leather-600) 55%, transparent);
  outline-offset: 2px;
}

.ds-btn-default {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 32px;
  padding: 0 15px;
  border: 1px solid var(--color-parchment-200);
  border-radius: 8px;
  background: #ffffff;
  color: var(--color-ink-900);
  font-family: var(--font-sans);
  font-size: 14px;
  font-weight: 400;
  line-height: 1;
  cursor: pointer;
  transition: color 200ms ease, border-color 200ms ease;
}
.ds-btn-default:hover {
  border-color: var(--color-leather-600);
  color: var(--color-leather-700);
}
.ds-btn-default:active {
  border-color: var(--color-leather-700);
  color: var(--color-leather-700);
}
.ds-btn-default:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--color-leather-600) 45%, transparent);
  outline-offset: 2px;
}

.ds-input {
  box-sizing: border-box;
  width: 100%;
  height: 32px;
  padding: 0 11px;
  border: 1px solid var(--color-parchment-200);
  border-radius: 8px;
  background: #ffffff;
  color: var(--color-ink-900);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  transition: border-color 200ms ease, box-shadow 200ms ease;
}
.ds-input::placeholder {
  color: var(--color-ink-500);
}
.ds-input:hover {
  border-color: var(--color-parchment-300);
}
.ds-input:focus {
  border-color: var(--color-leather-600);
  outline: none;
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--color-leather-600) 18%, transparent);
}

.ds-tag {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 7px;
  border: 1px solid var(--color-parchment-200);
  border-radius: 4px;
  background: var(--color-parchment-100);
  color: var(--color-ink-700);
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 400;
  line-height: 20px;
  white-space: nowrap;
}

.ds-card {
  display: block;
  padding: 16px;
  border: 1px solid var(--color-parchment-200);
  border-radius: 12px;
  background: #ffffff;
  color: var(--color-ink-900);
  font-family: var(--font-sans);
  box-shadow: 0 1px 3px 0 #0000001a, 0 1px 2px -1px #0000001a;
}
.ds-card__eyebrow {
  margin: 0 0 4px;
  color: var(--color-ink-500);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.5;
  letter-spacing: 0.025em;
  text-transform: uppercase;
}
.ds-card__title {
  margin: 0;
  color: var(--color-ink-900);
  font-family: var(--font-reading);
  font-size: 18px;
  font-weight: 400;
  line-height: 1.375;
}
.ds-card__meta {
  margin: 4px 0 0;
  color: var(--color-ink-500);
  font-size: 12px;
  line-height: 1.5;
}

.ds-nav {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--color-parchment-100) 80%, transparent);
  font-family: var(--font-sans);
}
.ds-nav-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 36px;
  padding: 0 12px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
  text-decoration: none;
  transition: color 200ms ease, background-color 200ms ease;
}
.ds-nav-item--active {
  background: #ffffff;
  color: var(--color-leather-700);
  box-shadow: 0 1px 3px 0 #0000001a, 0 1px 2px -1px #0000001a;
}
.ds-nav-item--idle {
  background: transparent;
  color: var(--color-ink-500);
}
.ds-nav-item--idle:hover {
  color: var(--color-ink-900);
}
.ds-nav-item:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--color-leather-600) 45%, transparent);
  outline-offset: 2px;
}

.ds-chapter-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 44px;
  padding: 6px 8px;
  border: 0;
  border-radius: 6px;
  background: var(--color-leather-100);
  color: var(--color-leather-700);
  font-family: var(--font-sans);
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}
.ds-chapter-row__badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 9999px;
  background: var(--color-leather-600);
  color: #ffffff;
  font-size: 11px;
  flex-shrink: 0;
}
.ds-chapter-row__title {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-chapter-row__meta {
  flex-shrink: 0;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.ds-chapter-row__tracks {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0 8px 6px 32px;
}
.ds-chapter-row__bar {
  display: block;
  height: 2px;
  overflow: hidden;
  border-radius: 9999px;
  background: color-mix(in srgb, #ffffff 70%, transparent);
}
.ds-chapter-row__fill {
  display: block;
  width: 64%;
  height: 100%;
  border-radius: inherit;
  background: color-mix(in srgb, var(--color-leather-600) 55%, transparent);
}
.ds-chapter-row:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--color-leather-600) 45%, transparent);
  outline-offset: 2px;
}

.ds-reader-arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border: 1px solid color-mix(in srgb, var(--color-parchment-200) 80%, transparent);
  border-radius: 9999px;
  background: color-mix(in srgb, #ffffff 92%, transparent);
  color: var(--color-leather-700);
  box-shadow: 0 8px 24px rgb(74 54 38 / 14%);
  backdrop-filter: blur(6px);
  cursor: pointer;
  transition: background-color 200ms ease, border-color 200ms ease, color 200ms ease;
}
.ds-reader-arrow:hover:not(:disabled) {
  border-color: var(--color-leather-600);
  background: #ffffff;
  color: var(--color-ink-900);
}
.ds-reader-arrow:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--color-leather-600) 55%, transparent);
  outline-offset: 2px;
}
.ds-reader-arrow:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-comparison {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
  font-family: var(--font-sans);
}
.ds-pane {
  min-width: 0;
  padding: 16px;
  background: #ffffff;
}
.ds-pane--source {
  background: color-mix(in srgb, var(--color-parchment-50) 70%, transparent);
}
.ds-pane__label {
  display: block;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--color-parchment-200);
  color: var(--color-ink-500);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: 0.025em;
  text-transform: uppercase;
}
.ds-pane__text {
  margin: 0;
  color: var(--color-ink-900);
  font-family: var(--font-reading);
  font-size: 17.2px;
  line-height: 1.8;
  text-align: justify;
  hyphens: auto;
}
.ds-pane__text mark {
  background: color-mix(in srgb, var(--color-annotation-amber) 80%, transparent);
  color: inherit;
}
